                        /* 6.110.0 */
                        size: isFinite(t.size) ? clamp(+t.size, TEXT_MIN, TEXT_MAX) : 1,
                        rot: isFinite(t.rot) ? clamp(+t.rot, -180, 180) : 0,
                        align: t.align || "center",
